// Inline, CSS-animated Shopify-specific illustrations (Codex SVGs in ./svg,
// generated by `node scripts/build-ikas-visuals.mjs shopify`). Same contract as
// IkasVisual: final state in the HTML, motion opt-in via IkasMotionScope
// (`ikas-visible` once, `ikas-in-view` for loops; mounted by ShopifyMotionScope),
// CSS under "shopify visuals" in globals.css, reduced motion shows the end state.

import { SHOPIFY_VISUALS, type ShopifyVisualName } from './generated';
import { ShopifyIcon } from '@/components/e-commerce/ShopifyMark';

interface ShopifyArtworkProps {
  name: ShopifyVisualName;
  /** Accessible description; omit for purely decorative use. */
  label?: string;
  /** HTML labels for `slot-*` boxes (keyed by slot id). */
  slotLabels?: Record<string, string>;
  /** Keep ambient loops running while on screen. */
  loop?: boolean;
  className?: string;
}

export default function ShopifyArtwork({ name, label, slotLabels, loop = false, className = '' }: ShopifyArtworkProps) {
  const visual = SHOPIFY_VISUALS[name];
  const slots = visual.slots as Record<string, { left: number; top: number; width: number; height: number }>;
  return (
    <figure
      data-ikas-reveal=""
      className={`shopify-art shopify-art--${name} relative m-0 ${className}`}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
    >
      <div data-ikas-loop={loop ? '' : undefined} className="sv-art" dangerouslySetInnerHTML={{ __html: visual.markup }} />
      {Object.entries(slots).map(([id, box]) => {
        const style = { left: `${box.left}%`, top: `${box.top}%`, width: `${box.width}%`, height: `${box.height}%` };
        if (id === 'slot-shopify-mark') {
          return <span key={id} aria-hidden="true" className="sv-slot sv-slot-shopify-mark absolute flex items-center gap-1.5 whitespace-nowrap text-[clamp(10px,1.3vw,14px)] font-bold text-gray-900" style={style}><ShopifyIcon size={18} />Shopify</span>;
        }
        const text = slotLabels?.[id];
        return text ? <span key={id} aria-hidden="true" className={`sv-slot sv-${id} absolute flex items-center ${id.startsWith('slot-chip') ? 'ps-2' : 'justify-center text-center'} text-[clamp(9px,1.25vw,13px)] font-semibold leading-tight text-gray-700`} style={style}>{text}</span> : null;
      })}
    </figure>
  );
}
